// Import rules for the Journey-to-the-West characters under Assets/Characters (generated by the _models pipeline).
using UnityEditor;
using UnityEngine;

public class CharacterImportRules : AssetPostprocessor
{
    const string Root = "Assets/Characters/";

    void OnPreprocessModel()
    {
        if (!assetPath.StartsWith(Root)) return;
        var mi = (ModelImporter)assetImporter;
        mi.globalScale = 1f;
        mi.useFileScale = true;
        mi.importBlendShapes = assetPath.EndsWith("_rigged.fbx");   // viseme shape keys (A/I/U/E/O) on the rigged characters
        mi.importAnimation = false;
        mi.materialImportMode = ModelImporterMaterialImportMode.ImportStandard;
        mi.materialLocation = ModelImporterMaterialLocation.InPrefab;
        if (assetPath.Contains("/Animations/"))
        {
            // armature-only clips from _models/ride.py; avatar = copy of <name>_rigged (set by WukongFlightSetup)
            mi.animationType = ModelImporterAnimationType.Human;
            mi.importAnimation = true;
            mi.optimizeGameObjects = false;
        }
        else if (assetPath.EndsWith("_rigged.fbx"))
        {
            mi.animationType = ModelImporterAnimationType.Human;
            mi.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
            mi.optimizeGameObjects = false;
        }
        else
        {
            mi.animationType = ModelImporterAnimationType.None;   // props (e.g. wukong_staff.fbx)
        }
    }

    void OnPreprocessTexture()
    {
        if (!assetPath.StartsWith(Root)) return;
        var ti = (TextureImporter)assetImporter;
        string n = System.IO.Path.GetFileNameWithoutExtension(assetPath).ToLowerInvariant();
        // high clarity for close-up PC VR: full 4K, high-quality compression (BC7/BC5), mipmaps, 8x anisotropic
        ti.maxTextureSize = 4096;
        ti.textureCompression = TextureImporterCompression.CompressedHQ;
        ti.crunchedCompression = false;
        ti.mipmapEnabled = true;
        ti.anisoLevel = 8;
        ti.filterMode = FilterMode.Trilinear;
        if (n.EndsWith("_normal"))
        {
            ti.textureType = TextureImporterType.NormalMap;
        }
        else if (n.Contains("metallic"))
        {
            ti.textureType = TextureImporterType.Default;
            ti.sRGBTexture = false;
            ti.alphaSource = TextureImporterAlphaSource.FromInput;
        }
        else
        {
            ti.textureType = TextureImporterType.Default;
            ti.sRGBTexture = true;
        }
    }
}
